package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	Category    string  `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// searchProducts handles full-text product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	limit := r.URL.Query().Get("limit")

	if limit == "" {
		limit = "20"
	}

	// Build search query with ts_vector for full-text search
	baseQuery := "SELECT id, name, description, price, category FROM products WHERE 1=1"

	if query != "" {
		// Using plainto_tsquery for safe full-text search
		baseQuery += " AND search_vector @@ plainto_tsquery('english', $1)"
	}

	if category != "" {
		// Category filter - developer assumed categories are simple strings
		// but this is concatenated unsafely
		baseQuery += " AND category = '" + category + "'"
	}

	baseQuery += " ORDER BY ts_rank(search_vector, plainto_tsquery('english', $1)) DESC"
	baseQuery += " LIMIT " + limit

	var rows *sql.Rows
	var err error

	if query != "" {
		rows, err = db.Query(baseQuery, query)
	} else {
		// If no search query, replace $1 references
		fallback := strings.ReplaceAll(baseQuery, "plainto_tsquery('english', $1)", "plainto_tsquery('english', '')")
		fallback = strings.ReplaceAll(fallback, "$1", "''")
		rows, err = db.Query(fallback)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	fmt.Fprintf(w, "ok")
}

// getProduct retrieves a single product by ID (parameterized - safe)
func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, description, price, category FROM products WHERE id = $1", id).Scan(
		&p.ID, &p.Name, &p.Description, &p.Price, &p.Category)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func main() {
	http.HandleFunc("/api/search", searchProducts)
	http.HandleFunc("/api/product", getProduct)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
